-- =====================================================
-- PROSES DUPLIKAT IVA - 1 FILE UNTUK PRODUCTION
-- Cara pakai (1 klik): buka phpMyAdmin > pilih DB > Import > pilih file ini > Go
-- Atau via mysql: mysql -u root -D <nama_db> < file_ini.sql
-- Aman diulang: pakai INSERT IGNORE + backup di-drop dulu
-- Skema ID baru: ID lama + 'IVA' (tanpa strip), kode tetap sama
--   Contoh: 17564 -> 17564IVA, 17564-9 -> 17564IVA-9
-- =====================================================

-- 0. BACKUP (di-drop dulu biar bersih tiap jalan)
DROP TABLE IF EXISTS backup_iva_master_products;
CREATE TABLE backup_iva_master_products AS SELECT * FROM master_products WHERE id IN ('17564','17565','17568','17570','17572','18395','18396','18397','24442','24628','SJA 11940','SJA 11894');

DROP TABLE IF EXISTS backup_iva_master_packaging;
CREATE TABLE backup_iva_master_packaging AS SELECT * FROM master_products_packaging WHERE product_id IN ('17564','17565','17568','17570','17572','18395','18396','18397','24442','24628','SJA 11940','SJA 11894');

DROP TABLE IF EXISTS backup_iva_so_item;
CREATE TABLE backup_iva_so_item AS SELECT si.* FROM penjualan_so_item si JOIN penjualan_so s ON s.id=si.so_id
WHERE ((s.code='5C098' AND si.product_packaging_id='17564-9') OR (s.code='6J001' AND si.product_packaging_id='SJA 11940-9')
OR (s.code='5H025' AND si.product_packaging_id='17568-7') OR (s.code='5I030' AND si.product_packaging_id IN ('17568-7','17572-7'))
OR (s.code='6D031' AND si.product_packaging_id='18395-9') OR (s.code='5L069' AND si.product_packaging_id='18396-9')
OR (s.code='5L068' AND si.product_packaging_id='17572-7') OR (s.code='6E085' AND si.product_packaging_id='24628-9')
OR (s.code='4J084' AND si.product_packaging_id='24442-7') OR (s.code='5A045' AND si.product_packaging_id='24442-7')
OR (s.code='6H092' AND si.product_packaging_id IN ('SJA 11894-9','17570-9')) OR (s.code='6G001' AND si.product_packaging_id IN ('17565-9','18397-9')));

DROP TABLE IF EXISTS backup_iva_do_item;
CREATE TABLE backup_iva_do_item AS SELECT di.* FROM penjualan_do_item di JOIN penjualan_do d ON d.id=di.do_id JOIN penjualan_so s ON s.id=d.so_id
WHERE ((s.code='5C098' AND di.product_packaging_id='17564-9') OR (s.code='6J001' AND di.product_packaging_id='SJA 11940-9')
OR (s.code='5H025' AND di.product_packaging_id='17568-7') OR (s.code='5I030' AND di.product_packaging_id IN ('17568-7','17572-7'))
OR (s.code='6D031' AND di.product_packaging_id='18395-9') OR (s.code='5L069' AND di.product_packaging_id='18396-9')
OR (s.code='5L068' AND di.product_packaging_id='17572-7') OR (s.code='6E085' AND di.product_packaging_id='24628-9')
OR (s.code='4J084' AND di.product_packaging_id='24442-7') OR (s.code='5A045' AND di.product_packaging_id='24442-7')
OR (s.code='6H092' AND di.product_packaging_id IN ('SJA 11894-9','17570-9')) OR (s.code='6G001' AND di.product_packaging_id IN ('17565-9','18397-9')));

DROP TABLE IF EXISTS backup_iva_min_stock;
CREATE TABLE backup_iva_min_stock AS SELECT * FROM master_product_min_stocks WHERE product_packaging_id IN ('17564-9','17565-9','17568-7','17570-9','17572-7','18395-9','18396-9','18397-9','24442-7','24442-9','24628-7','24628-9','SJA 11894-7','SJA 11894-9','SJA 11940-9');

